items.inputSchema:
{
  "type": "object",
  "required": [
    "catalog"
  ],
  "properties": {
    "catalog": {
      "type": "object",
      "required": [
        "query"
      ],
      "properties": {
        "query": {
          "type": "string",
          "description": "Search query string."
        },
        "pagination": {
          "type": "object",
          "properties": {
            "limit": {
              "type": "integer",
              "description": "Max results per type (1-10). Defaults to 5.",
              "default": 5,
              "minimum": 1,
              "maximum": 10
            }
          }
        }
      }
    }
  }
}

{
  "type": "object",
  "properties": {
    "collection": {
      "type": "string",
      "description": "Collection handle to browse (e.g. \"best-sellers\", \"new-arrivals\"). Omit to list all collections. Use \"all\" to browse every product."
    },
    "navigate": {
      "type": "boolean",
      "description": "When true, navigate the browser to the collection page after loading data. Set true for user intents like \"browse to\", \"go to\", \"show me\", \"open\", \"take me to\" a collection. Requires a collection handle. Defaults to false."
    },
    "sort_by": {
      "type": "string",
      "description": "Sort order. Options: best-selling (default), price-ascending, price-descending, title-ascending, title-descending, created-descending, created-ascending."
    },
    "page": {
      "type": "number",
      "description": "Page number for pagination (starts at 1). Each page returns up to 30 products."
    }
  }
}

{
  "type": "object",
  "properties": {
    "catalog": {
      "type": "object",
      "description": "Product detail parameters.",
      "properties": {
        "id": {
          "type": "string",
          "description": "Storefront API Product GID, product handle, or product URL path. Custom app product paths and Shopify standard /products/<handle> paths are supported. The id field from search_catalog or browse_store can be passed directly. If omitted, uses the current page's product."
        },
        "navigate": {
          "type": "boolean",
          "description": "When true, navigate the browser to the product page after fetching details. Set true for user intents like \"show me\", \"open\", \"view\", \"go to\", \"take me to\" a product. Defaults to false. If the user specified partial options (e.g. only a color), prefer show_variant with selected_options instead."
        },
        "selected_options": {
          "type": "array",
          "description": "Known product option selections to filter available_options. Use exact option names and values from search_catalog options or a prior get_product available_options entry.",
          "items": {
            "type": "object",
            "properties": {
              "name": {
                "type": "string",
                "description": "Option name, e.g. \"Size\" or \"Color\"."
              },
              "value": {
                "type": "string",
                "description": "Option value, e.g. \"160cm\" or \"Fiberglass\"."
              }
            },
            "required": [
              "name",
              "value"
            ]
          }
        }
      }
    }
  }
}

{
  "type": "object",
  "required": [
    "catalog"
  ],
  "properties": {
    "catalog": {
      "type": "object",
      "description": "Provide EITHER variant_id OR selected_options. Handle is required unless the user is already on the product page.",
      "properties": {
        "handle": {
          "type": "string",
          "description": "Product handle. If omitted, uses the current product page's handle."
        },
        "variant_id": {
          "type": [
            "string",
            "number"
          ],
          "description": "ProductVariant ID from get_product variants[].id, e.g. \"gid://shopify/ProductVariant/123\", or the numeric variant ID. Use when the user picked a specific fully-specified variant. Omit when using selected_options."
        },
        "selected_options": {
          "type": "array",
          "description": "Partial (or full) option selections, e.g. [{\"name\":\"Color\",\"value\":\"Purple\"}]. Use when the user names some options but not all (e.g. \"show me the purple shoe\" — pass only Color). The first matching available variant will be selected automatically. Use exact option names and values from get_product available_options or search_catalog options.",
          "items": {
            "type": "object",
            "properties": {
              "name": {
                "type": "string"
              },
              "value": {
                "type": "string"
              }
            }
          }
        }
      }
    }
  }
}

{
  "type": "object",
  "required": [
    "cart"
  ],
  "properties": {
    "cart": {
      "type": "object",
      "required": [
        "line_items"
      ],
      "properties": {
        "line_items": {
          "type": "array",
          "description": "The items the new cart holds.",
          "minItems": 1,
          "maxItems": 100,
          "items": {
            "type": "object",
            "required": [
              "item",
              "quantity"
            ],
            "properties": {
              "item": {
                "type": "object",
                "required": [
                  "id"
                ],
                "properties": {
                  "id": {
                    "type": "string",
                    "description": "ProductVariant GID, e.g. \"gid://shopify/ProductVariant/123\": variant_id from search_catalog or browse_store, variants[].id from get_product, or line_items[].item.id from a cart result."
                  }
                }
              },
              "quantity": {
                "type": "integer",
                "description": "How many of this item the line holds.",
                "minimum": 1
              }
            }
          }
        }
      }
    }
  }
}

{
  "type": "object",
  "required": [
    "cart"
  ],
  "properties": {
    "id": {
      "type": "string",
      "description": "Optional: the page has one cart, the shopper's, and update_cart always acts on it. When given (the id from a cart result), it is compared with the current cart, and a mismatch changes nothing."
    },
    "cart": {
      "type": "object",
      "properties": {
        "line_items": {
          "type": "array",
          "description": "The complete set of lines the cart holds afterwards. Empty empties the cart; absent leaves the lines as they are.",
          "maxItems": 100,
          "items": {
            "type": "object",
            "required": [
              "item",
              "quantity"
            ],
            "properties": {
              "id": {
                "type": "string",
                "description": "Existing cart line id (line_items[].id from a cart result). Absent for an item that is not in the cart yet."
              },
              "item": {
                "type": "object",
                "required": [
                  "id"
                ],
                "properties": {
                  "id": {
                    "type": "string",
                    "description": "ProductVariant GID, e.g. \"gid://shopify/ProductVariant/123\": variant_id from search_catalog or browse_store, variants[].id from get_product, or line_items[].item.id from a cart result."
                  }
                }
              },
              "quantity": {
                "type": "integer",
                "description": "How many of this item the line holds.",
                "minimum": 1
              }
            }
          }
        }
      }
    }
  }
}

{
  "type": "object",
  "required": [
    "ask"
  ],
  "properties": {
    "ask": {
      "type": "object",
      "description": "The question and optional buyer context.",
      "required": [
        "query"
      ],
      "properties": {
        "query": {
          "type": "string",
          "maxLength": 10000,
          "description": "The shopper's question, in natural language."
        },
        "context": {
          "type": "object",
          "description": "Optional buyer context, such as the shopper's country or language. Send only what the question needs.",
          "additionalProperties": true,
          "properties": {
            "intent": {
              "type": "string",
              "description": "What the shopper is trying to do, when it adds to the question (e.g. \"returning a gift they received\")."
            },
            "address_country": {
              "type": "string",
              "description": "The buyer's country, e.g. \"US\"."
            },
            "address_region": {
              "type": "string",
              "description": "The buyer's state or region, e.g. \"CA\"."
            },
            "language": {
              "type": "string",
              "description": "The preferred language, e.g. \"en\"."
            }
          }
        }
      }
    }
  }
}
